[1513]={["atomIDs"]={"1513:description:1-54","1513:description:56-111","1513:description:113-152","1513:description:154-248","1513:description:253-348","1513:objective:1-116"},["opening"]="Dogran's pendant was the bait for the circle in Neeru's tent. Gan'rul warned against pride in the confrontation and wanted the pendant back afterward so he could bring news to Zankaja.",["pending"]="{actor} would summon and subdue a succubus with Dogran's Pendant and return it to Gan'rul.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the succubus binding assignment and returned Dogran's Pendant to Gan'rul.",["sourceClassMask"]="256",["sourceHash"]="7a136981e26862c57a701e8e8932900511e814034ccd4ffe3f5db34821d777b5",["sourceMapID"]="?",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
