[1640]={["atomIDs"]={"1640:description:1-15","1640:description:18-30","1640:description:35-113","1640:objective:1-32"},["opening"]="Bartleby answered the demand for his mug with a threat. The tavern lesson now depended on beating him and speaking afterward.",["pending"]="{actor} would beat Bartleby and talk to him afterward.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the Bartleby contest and ensuing conversation.",["sourceClassMask"]="1",["sourceHash"]="55a72a1c2e845a70f18fda1743773a157464121adcb32e362d7fa6a1e5bfe9bd",["sourceMapID"]="?",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
