[1643]={["atomIDs"]={"1643:description:1-80","1643:description:82-121","1643:description:123-153","1643:description:155-189","1643:description:191-268","1643:description:273-320","1643:description:322-409","1643:objective:1-60"},["opening"]="Duthorian's test sought noble need within the city rather than an enemy outside it. Stephanie Turner in the Trade District was the person whose reliance on kindness could give that teaching practical form.",["pending"]="{actor} planned to find Stephanie Turner.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} found Stephanie Turner in Stormwind.",["sourceClassMask"]="2",["sourceHash"]="61a1a8f6d6cc1874cd22897a0bff5c7e39e35dc1cc7388e35d84186e6134d698",["sourceMapID"]="?",["sourceRaceMask"]="1",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[1644]={["atomIDs"]={"1644:description:1-100","1644:description:105-236","1644:description:238-320","1644:description:325-336","1644:description:338-362","1644:description:364-402","1644:description:407-511","1644:objective:1-54"},["opening"]="Feeding and sheltering orphaned children had left Stephanie no time to clothe them. Her husband gathered supplies, but ten pieces of linen would let her sew what the children still lacked.",["pending"]="{actor} meant to bring ten Linen Cloth to Stephanie.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered ten Linen Cloth to Stephanie Turner.",["sourceClassMask"]="2",["sourceHash"]="d5a8680672f84d778cfda34d4e69d7290aeff3bfaa9b9a5b759b7aff17be652b",["sourceMapID"]="?",["sourceRaceMask"]="1",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
